/// <summary>
/// Class created for LaserNet Reprint - SO
/// </summary>
public class METShipmentBundleReprintController extends SrsReportRunController
{
}

Method.Source:
/// <summary>
/// Run method
/// </summary>
public void run()
{
    return; // To stop the execution for outer controller class
}

/// <summary>
/// execute Report
/// </summary>
/// <param name = "shipmentLoadHeaderList">Shipment Load header list</param>
/// <param name = "_sRSPrintDestinationSettings"printer settings></param>
/// <param name = "isInBatch">In batch</param>
public void executeReport(Args                          _args, 
                          SRSPrintDestinationSettings   _sRSPrintDestinationSettings,
                          boolean                       _isInBatch = false)
{
    FormRun         formRun = _args.caller();
    Map             map = formRun.getFinalizationHeaderMap();
    MapIterator     mapIterator = new MapIterator(map);

    METSalesOrderShipmentLoadHeader             shipmentLoadHeader;
    METOrderShipmentBundlingReportHeaderTmp     bundlingReportHeaderTmp;

    while (mapIterator.more())
    {
        shipmentLoadHeader = METSalesOrderShipmentLoadHeader::findByRecId(mapIterator.key());

        if (shipmentLoadHeader.LoadStatus == MetLoadStatus::Shipped)
        {
            bundlingReportHeaderTmp.LoadID = shipmentLoadHeader.LoadId;
            bundlingReportHeaderTmp.ShipmentID = shipmentLoadHeader.ShipmentId;
            bundlingReportHeaderTmp.Route = shipmentLoadHeader.Route;
            bundlingReportHeaderTmp.RouteStopNum = shipmentLoadHeader.RouteStopNum;
            bundlingReportHeaderTmp.OrderTransactionType = shipmentLoadHeader.TransactionType;
            bundlingReportHeaderTmp.insert();
        }
        else
        {
            warning(strFmt("@MET:METLoadNotFullyShipped", shipmentLoadHeader.LoadId));//Load %1 is not fully shipped
        }

        mapIterator.next();
    }

    while select bundlingReportHeaderTmp
        order by LoadID, Route, RouteStopNum, OrderTransactionType asc
    {
        SrsReportRunController orderShipmentBundlePrintController = new SrsReportRunController();

        if (bundlingReportHeaderTmp.OrderTransactionType == METOrderTransactionType::SalesOrder)
        {
            orderShipmentBundlePrintController.parmReportName(ssrsReportStr(METSalesOrderShipmentBundlingReport, NewReport));
        }
        else
        {
            orderShipmentBundlePrintController.parmReportName(ssrsReportStr(METTransferOrderShipmentBundlingReport, Report));
        }

        if (_isInBatch)
        {
            orderShipmentBundlePrintController.parmExecutionMode(SysOperationExecutionMode::ScheduledBatch);
        }
        else    
        {
            orderShipmentBundlePrintController.parmExecutionMode(SysOperationExecutionMode::Synchronous);
        }
        orderShipmentBundlePrintController.parmShowDialog(false);
        orderShipmentBundlePrintController.parmLoadFromSysLastValue(false);

        METOrderShipmentBundlingReportContract orderShipmentBundlePrintContract = orderShipmentBundlePrintController.parmReportContract().parmRdpContract();

        orderShipmentBundlePrintContract.parmLoadId(bundlingReportHeaderTmp.LoadID);
        orderShipmentBundlePrintContract.parmShipmentId(bundlingReportHeaderTmp.ShipmentID);
        orderShipmentBundlePrintContract.parmIsFirstReport(true); // For reprint we need to always print DGN(LoadHeaderReport)
        orderShipmentBundlePrintContract.parmTransactionType(bundlingReportHeaderTmp.OrderTransactionType);

        orderShipmentBundlePrintController.parmReportContract().parmPrintSettings(_sRSPrintDestinationSettings);
        orderShipmentBundlePrintController.startOperation();
    }
}

/// <summary>
/// Main method
/// </summary>
/// <param name = "_args">args</param>
public static void main(Args    _args)
{
    FormRun         formRun = _args.caller();
    Map             map = formRun.getFinalizationHeaderMap();

    METShipmentBundleReprintController controller = new METShipmentBundleReprintController();

    if (!map.elements())
    {
        throw warning("@MET:METShipmentNotMarked"); //No shipment selected to reprint
    }

    METSalesOrderShipmentLoadHeader             shipmentLoadHeader = _args.record() as METSalesOrderShipmentLoadHeader;

    if (shipmentLoadHeader.TransactionType == METOrderTransactionType::SalesOrder)
    {
        controller.parmReportName(ssrsReportStr(METSalesOrderShipmentBundlingReport, NewReport));
    }
    else
    {
        controller.parmReportName(ssrsReportStr(METTransferOrderShipmentBundlingReport, Report));
    }

    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);
    controller.parmShowDialog(true);
    controller.parmDialogCaption("@MET:METReprintBundle");//Reprint Shipment Bundle

    controller.startOperation();

    if (!controller.isDialogCancelled())
    {
        sRSPrintDestinationSettings sRSPrintDestinationSettings = controller.parmReportContract().parmPrintSettings();

        if (controller.parmExecutionMode() != SysOperationExecutionMode::ScheduledBatch)
        {
            controller.executeReport(_args, sRSPrintDestinationSettings);
        }
        else
        {
            controller.executeReport(_args, sRSPrintDestinationSettings, true);
        }
    }
}

/// <summary>
/// method returns boolean value based on the dialog form cancelled or not
/// </summary>
/// <returns>boolean</returns>
public boolean isDialogCancelled()
{
    return dialogCanceled;
}
